    ih_update                        CHAR(1),  -- ih-update @98+1 PIC x
    PRIMARY KEY (ih_invoice, ih_test)
);

-- pl_invoice_line: pinvoice.dat (item-nos 1..); COBOL invoice-line (74 bytes)
CREATE TABLE pl_invoice_line (
    il_invoice                       INTEGER,  -- il-invoice @0+8 PIC 9(8)
    il_line                          SMALLINT,  -- il-line @8+1 binary-char
    il_product                       VARCHAR(13),  -- il-product @9+13 PIC x(13)
