    PRIMARY KEY (il_invoice, il_line)
);

-- pl_open_item: openitm5.dat; COBOL oi-header (109 bytes)
CREATE TABLE pl_open_item (
    oi_nos                           VARCHAR(6),  -- oi-nos @0+6 PIC x(6)
