    oi_carriage                      NUMERIC(9,2),  -- oi-carriage @59+5 PIC s9(7)v99 COMP-3
    oi_vat                           NUMERIC(9,2),  -- oi-vat @64+5 PIC s9(7)v99 COMP-3
    oi_discount                      NUMERIC(9,2),  -- oi-discount @69+5 PIC s9(7)v99 COMP-3
    oi_e_vat                         NUMERIC(9,2),  -- oi-e-vat @74+5 PIC s9(7)v99 COMP-3
    oi_c_vat                         NUMERIC(9,2),  -- oi-c-vat @79+5 PIC s9(7)v99 COMP-3
    oi_paid                          NUMERIC(9,2),  -- oi-paid @84+5 PIC s9(7)v99 COMP-3
    oi_status                        SMALLINT,  -- oi-status @89+1 PIC 9
    oi_deduct_days                   SMALLINT,  -- oi-deduct-days @90+1 binary-char
    oi_deduct_amt                    NUMERIC(5,2),  -- oi-deduct-amt @91+4 PIC s999v99 COMP
    oi_deduct_vat                    NUMERIC(5,2),  -- oi-deduct-vat @95+4 PIC s999v99 COMP
