-- pl_deleted_folio_no: delfolio.dat (sequential, surrogate id); COBOL del-inv-nos-record (19 bytes)
CREATE TABLE pl_deleted_folio_no (
    id                               BIGINT,  -- surrogate / single-record id
    del_inv_nos                      INTEGER,  -- del-inv-nos @0+8 PIC 9(8)
