-- pl_payment: pay.dat; COBOL pay-record (237 bytes)
CREATE TABLE pl_payment (
    pay_supl_key                     VARCHAR(7),  -- pay-supl-key @0+7 PIC x(7)
    pay_nos                          SMALLINT,  -- pay-nos @7+1 binary-char
    pay_cont                         CHAR(1),  -- pay-cont @8+1 PIC x
    pay_date                         DATE,  -- pay-date @9+4 binary-long; COBOL integer date (FUNCTION DATE-OF-INTEGER)
    pay_cheque                       INTEGER,  -- pay-cheque @13+4 binary-long
    pay_sortcode                     INTEGER,  -- pay-sortcode @17+4 binary-long
    pay_account                      INTEGER,  -- pay-account @21+4 binary-long
    pay_gross                        NUMERIC(9,2),  -- pay-gross @25+5 PIC s9(7)v99 COMP-3
    PRIMARY KEY (pay_supl_key, pay_nos)
);
-- pl_payment_line: OCCURS 9 of filler
CREATE TABLE pl_payment_line (
    pay_supl_key                     VARCHAR(7),
    pay_nos                          SMALLINT,
    seq_no                           SMALLINT,
    pay_folio                        INTEGER,
    pay_period                       SMALLINT,
    pay_value                        NUMERIC(9,2),
    pay_deduct                       NUMERIC(5,2),
    pay_invoice                      VARCHAR(10),
    PRIMARY KEY (pay_supl_key, pay_nos, seq_no),
    FOREIGN KEY (pay_supl_key, pay_nos) REFERENCES pl_payment (pay_supl_key, pay_nos)
);

-- irs_nominal: acnts.dat; COBOL nl-record (116 bytes)
CREATE TABLE irs_nominal (
    nl_owning                        INTEGER,  -- nl-owning @0+5 PIC 9(5)
    nl_sub_nominal                   INTEGER,  -- nl-sub-nominal @5+5 PIC 9(5)
