    nl_name                          VARCHAR(24),  -- nl-name @11+24 PIC x(24)
    nl_dr                            NUMERIC(10,2),  -- nl-dr @35+8 PIC 9(8)v99 COMP
    nl_cr                            NUMERIC(10,2),  -- nl-cr @43+8 PIC 9(8)v99 COMP
    nl_ac                            CHAR(1),  -- nl-ac @115+1 PIC x
    PRIMARY KEY (nl_owning, nl_sub_nominal)
);
-- irs_nominal_nl_dr_last: OCCURS 4 of nl-dr-last
CREATE TABLE irs_nominal_nl_dr_last (
    nl_owning                        INTEGER,
