    nl_dr_last                       NUMERIC(10,2),
    PRIMARY KEY (nl_owning, nl_sub_nominal, seq_no),
    FOREIGN KEY (nl_owning, nl_sub_nominal) REFERENCES irs_nominal (nl_owning, nl_sub_nominal)
);
-- irs_nominal_nl_cr_last: OCCURS 4 of nl-cr-last
CREATE TABLE irs_nominal_nl_cr_last (
    nl_owning                        INTEGER,
