    FOREIGN KEY (nl_owning, nl_sub_nominal) REFERENCES irs_nominal (nl_owning, nl_sub_nominal)
);

-- irs_system: IRS system.dat; COBOL system-record (312 bytes)
-- excluded: pass_word (plaintext credential; replaced by hashed credentials / secret store, see 05-ws-domain-mapping.md §3)
CREATE TABLE irs_system (
    id                               BIGINT,  -- surrogate / single-record id
    run_date                         VARCHAR(8),  -- run-date @0+8 PIC x(8)
    suser                            VARCHAR(24),  -- suser @8+24 PIC x(24)
    client                           VARCHAR(24),  -- client @32+24 PIC x(24)
    address_1                        VARCHAR(24),  -- address-1 @56+24 PIC x(24)
    address_2                        VARCHAR(24),  -- address-2 @80+24 PIC x(24)
    address_3                        VARCHAR(24),  -- address-3 @104+24 PIC x(24)
    address_4                        VARCHAR(24),  -- address-4 @128+24 PIC x(24)
    start_date                       VARCHAR(8),  -- start-date @152+8 PIC x(8)
    end_date                         VARCHAR(8),  -- end-date @160+8 PIC x(8)
    fn_1                             VARCHAR(9),  -- fn-1 @168+9 PIC x(9)
    fn_2                             VARCHAR(10),  -- fn-2 @177+10 PIC x(10)
    fn_3                             VARCHAR(8),  -- fn-3 @187+8 PIC x(8)
    fn_4                             VARCHAR(8),  -- fn-4 @195+8 PIC x(8)
    fn_5                             VARCHAR(12),  -- fn-5 @203+12 PIC x(12)
    system_ops                       CHAR(1),  -- system-ops @216+1 PIC x
    next_post                        INTEGER,  -- next-post @221+5 PIC 9(5)
    vat                              NUMERIC(4,2),  -- vat @226+4 PIC 99v99
    vat2                             NUMERIC(4,2),  -- vat2 @230+4 PIC 99v99
    vat3                             NUMERIC(4,2),  -- vat3 @234+4 PIC 99v99
    pass_value                       SMALLINT,  -- pass-value @238+1 PIC 9
    save_sequ                        SMALLINT,  -- save-sequ @239+1 PIC 9
    system_work_group                VARCHAR(18),  -- system-work-group @240+18 PIC x(18)
    pl_app_created                   CHAR(1),  -- PL-App-Created @258+1 PIC x
    pl_approp_ac                     INTEGER,  -- PL-Approp-AC @259+5 PIC 9(5)
    print_spool_name                 VARCHAR(32),  -- Print-Spool-Name @264+32 PIC x(32)
    first_time_flag                  SMALLINT,  -- First-Time-FLag @296+1 PIC 9
    PRIMARY KEY (id)
);

-- irs_default: dflt.dat; COBOL default-record (256 bytes)
CREATE TABLE irs_default (
    id                               BIGINT,  -- surrogate / single-record id
    PRIMARY KEY (id)
);
